// Traditional mini-game renders as hashes: the 96x96 work must leave every Traditional frame (64 grid, one ink) byte-identical.
// `tradHashes()` uses only the pre-96 APIs, so the table in test/games96.ts was generated by running this very function on the commit before the 96 painters.
import { forceSpecies, newPet } from '../src/core/pet';
import { SPECIES } from '../src/core/speciesData';
import { makeRng } from '../src/core/minigames/rng';
import { newSession, pressButton, tickSession } from '../src/core/minigames/session';
import { paramsFor } from '../src/core/minigames/tuning';
import { GAME_ENTRIES } from '../src/ui/games/registry';
import { TICK_MS } from '../src/ui/scene';
import { renderScreen } from '../src/ui/screens';
import { hashMask } from './hash';

const T0 = 1_800_000_000_000 - (1_800_000_000_000 % TICK_MS);
export const TRAD_FAMS = ['dino', 'fox', 'fish', 'bird', 'cat', 'spirits', 'bunny', 'dragon', 'bot', 'slime', 'bug', 'alien'];

export function tradHashes(): Record<string, string> {
  const out: Record<string, string> = {};
  for (const fam of TRAD_FAMS) {
    const sp = SPECIES.find((s) => s.family === fam && s.stage === 'adult')!;
    const pet = newPet(T0, { seed: 9 }); forceSpecies(pet, sp.id); pet.named = true; pet.name = 'Rexie'; pet.hunger = 4; pet.happy = 2;
    for (const e of GAME_ENTRIES) {
      for (const upto of [400, 9000, 99999]) {
        const s = newSession(e.def, paramsFor(pet, e.def.id), 4); pressButton(s, 'b');
        const rng = makeRng(upto % 977 + 1);
        let t = 0;
        while (t < upto && s.phase === 'play') { s.pending = { ...s.pending, left: rng.chance(0.2), right: rng.chance(0.15), act: rng.chance(0.2) }; tickSession(s, 50); t += 50; }
        const r = renderScreen({ pet, tick: 3, mode: 'game', feedSel: 0, statsPage: 0, dexPage: 0, evo: null, scene: null, ms: T0 + upto, session: s });
        out[`${fam}/${e.def.id}/${upto}`] = hashMask(Array.from(r.buf.px, (v) => v & 0x7f));
      }
    }
  }
  return out;
}
